        /// <param name="maxIter">SDA doubling-step budget; &lt;=0 picks the library default (50).</param>
        public static RiccatiInfo dare(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                       ref floatMxN S, int maxIter = 0)
        {
